{var $v_items = ($p['items'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_topics = ($p['topics'] ?? null)}
{capture $c_8}
  {=ui_include('blocks/search-field.latte', ['p' => ['label' => ui_get($v_labels, ['search']), 'placeholder' => ui_get($v_labels, ['search']), 'value' => ui_coalesce([ui_get($v_labels, ['query']), ''])]])|noescape}
  {capture $c_2}
    {foreach ui_l($v_topics) as $v_t}
      {capture $c_1}
        {=ui_text(ui_get($v_t, ['title']))}
      {/capture}
      {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'outline', 'Size' => 'sm', 'Href' => ui_s(ui_tpl('#/faq/{0}', [ui_get($v_t, ['value'])])), 'Attrs' => ui_attrs(['data-testid', 'faq-topic'])], 'children' => $c_1])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Class' => 'flex-wrap'], 'children' => $c_2])|noescape}
  {capture $c_7}
    {capture $c_3}
      {=ui_text(ui_get($v_labels, ['popular']))}
    {/capture}
    {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_3])|noescape}
    {capture $c_6}
      {foreach ui_l($v_items) as $v_q}
        {var $v_i = $iterator->counter0}
        {if ui_t(ui_lt($v_i, 3))}
          {capture $c_5}
            {capture $c_4}
              {=ui_text(ui_get($v_q, ['question']))}
            {/capture}
            {=ui_include('ui/link/link.latte', ['p' => ['Href' => '#/faq', 'Variant' => 'default', 'Size' => 'sm'], 'children' => $c_4])|noescape}
          {/capture}
          {=ui_include('ui/list/list-item.latte', ['p' => ['Attrs' => ui_attrs(['data-testid', 'faq-popular'])], 'children' => $c_5])|noescape}
        {/if}
      {/foreach}
    {/capture}
    {=ui_include('ui/list/list.latte', ['p' => ['Class' => 'm-0 flex list-none flex-col gap-2 p-0'], 'children' => $c_6])|noescape}
  {/capture}
  {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2'], 'children' => $c_7])|noescape}
{/capture}
{=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '6', 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'faq-finder'])], 'children' => $c_8])|noescape}
